#!/bin/sh
# Генерирует UpdateConfig.swift из update_url.txt и pubkey.txt
HERE="$(cd "$(dirname "$0")" && pwd)"
cat > "$1" <<SW
// generated by release/make_config.sh
enum UpdateConfig {
    static let publicURL = "$(tr -d '\n ' < "$HERE/update_url.txt")"
    static let publicKey = "$(tr -d '\n ' < "$HERE/pubkey.txt")"
}
SW
